<?php
$uid=(int)me()['id'];$total=countq('SELECT COUNT(*) FROM usuarios WHERE ativo=1');$upcoming=countq('SELECT COUNT(*) FROM eventos WHERE inicio>=NOW() AND cancelado=0');$overdue=countq('SELECT COUNT(*) FROM mensalidades WHERE pago=0 AND mes<=?',[date('Y-m')]);$wardrobe=countq('SELECT COUNT(*) FROM figurinos WHERE devolvido=0');
$events=q('SELECT id,titulo,tipo,inicio,local FROM eventos WHERE inicio>=NOW() AND cancelado=0 ORDER BY inicio ASC LIMIT 5')->fetchAll();$notices=q('SELECT titulo,conteudo,criado_em FROM avisos ORDER BY criado_em DESC LIMIT 4')->fetchAll();
render_header('Visão geral');?><div class="hero"><div><div class="eyebrow">BEM-VINDO À INVERNADA</div><h1>Olá, <?=h(explode(' ',me()['name'])[0])?>! <span>✦</span></h1><p>Acompanhe o que acontece na Sentinela da Fronteira e mantenha tudo organizado.</p><a class="btn btn-light" href="<?=url('calendario')?>">Ver calendário →</a></div><img class="hero-logo" src="assets/logo-sentinela.png" alt="" aria-hidden="true" width="180" height="228"></div>
<section class="stats"><article class="stat"><span>Integrantes ativos</span><strong><?=number_format($total,0,',','.')?></strong><small>Comunidade da invernada</small></article><article class="stat"><span>Próximos eventos</span><strong><?=$upcoming?></strong><small>Ensaios e apresentações</small></article><article class="stat"><span>Mensalidades pendentes</span><strong><?=$overdue?></strong><small>Registros não quitados</small></article><article class="stat"><span>Figurinos emprestados</span><strong><?=$wardrobe?></strong><small>Itens aguardando devolução</small></article></section>
<div class="two-col"><section class="panel"><div class="section-head"><div><div class="eyebrow">PROGRAMAÇÃO</div><h2>Próximos compromissos</h2></div><a href="<?=url('eventos')?>">Ver todos →</a></div><?php if(!$events):?><p class="empty">Nenhum evento futuro cadastrado.</p><?php endif;foreach($events as $e):?><div class="item"><div class="date-pill"><strong><?=date('d',strtotime($e['inicio']))?></strong><small><?=date('m',strtotime($e['inicio']))?></small></div><div><strong><?=h($e['titulo'])?></strong><p><?=h($e['tipo'])?> · <?=h($e['local']?:'Local a definir')?> · <?=date('H:i',strtotime($e['inicio']))?></p></div></div><?php endforeach;?></section><section class="panel"><div class="section-head"><div><div class="eyebrow">COMUNICADOS</div><h2>Últimos avisos</h2></div><a href="<?=url('avisos')?>">Ver mural →</a></div><?php if(!$notices):?><p class="empty">Nenhum aviso publicado.</p><?php endif;foreach($notices as $n):?><div class="notice"><strong><?=h($n['titulo'])?></strong><p><?=h(mb_strimwidth($n['conteudo'],0,180,'…'))?></p><small><?=date('d/m/Y',strtotime($n['criado_em']))?></small></div><?php endforeach;?></section></div>
<?php render_footer();
